import {uid} from './storage.js';
import {icon} from './icons.js';
import {$,$$,esc,openForm,field,option,confirmAction,toast} from './ui.js';
import {formatTime} from './audio-engine.js';

/** CRUD de direção sonora, sem acoplar o editor ou a navegação ao AudioEngine. */
export function openSceneConfig(ctx,tab='layers') {
  const scene=ctx.scene(),state=ctx.state();
  const back=()=>openSceneConfig(ctx,tab);
  let content='';
  if(tab==='layers')content=`<p class="dialog-description">Camadas em loop entram com a cena. O crossfade mantém as transições suaves.</p><div class="config-list">${scene.layers.map(l=>`<div class="config-row"><span class="asset-mini">${icon('rain')}</span><div><strong>${esc(l.name)}</strong><small>${esc(state.audioAssets.find(a=>a.id===l.assetId||a.src===l.src)?.name||'Arquivo original')} · ${Math.round(l.volume*100)}%</small></div><button type="button" class="icon-btn" data-edit-layer="${esc(l.id)}" aria-label="Editar ${esc(l.name)}">${icon('edit')}</button><button type="button" class="icon-btn" data-remove-layer="${esc(l.id)}" aria-label="Remover ${esc(l.name)}">${icon('trash')}</button></div>`).join('')||'<p class="empty-small">Esta cena ainda não tem camadas.</p>'}</div><button type="button" class="btn outline full" id="addLayer">${icon('plus')} Adicionar camada</button><div class="config-music"><label class="field"><span>Música ao iniciar a cena</span><select id="sceneMusic">${option('','Continuar música atual',!scene.musicAssetId)}${state.audioAssets.filter(a=>a.kind==='music'||a.provider==='youtube').map(a=>option(a.id,a.name,a.id===scene.musicAssetId)).join('')}</select></label><small>Selecione uma faixa da biblioteca. A navegação entre páginas não interrompe a reprodução.</small></div>`;
  if(tab==='triggers')content=`<p class="dialog-description">Dispare um efeito ou uma sequência de ações pelo botão, pelo roteiro ou por uma tecla.</p><div class="config-list">${scene.triggers.map(t=>`<div class="config-row"><span class="asset-mini">${icon(t.cue?'bolt':'bell')}</span><div><strong>${esc(t.name)}</strong><small>${t.cue?'Cue composta':'Efeito sonoro'}${t.key?' · Tecla '+esc(t.key):''}</small></div><button type="button" class="icon-btn" data-edit-trigger="${esc(t.id)}" aria-label="Editar ${esc(t.name)}">${icon('edit')}</button><button type="button" class="icon-btn" data-remove-trigger="${esc(t.id)}" aria-label="Remover ${esc(t.name)}">${icon('trash')}</button></div>`).join('')||'<p class="empty-small">Nenhum gatilho configurado.</p>'}</div><button type="button" class="btn outline full" id="addTrigger">${icon('plus')} Adicionar gatilho</button><div class="section-heading"><h3>Cues compostas</h3><button type="button" class="btn subtle small" id="addCue">${icon('plus')} Criar cue</button></div>${(scene.cues||[]).map(c=>`<div class="config-row"><span class="asset-mini">${icon('bolt')}</span><div><strong>${esc(c.name)}</strong><small>${c.actions.length} ações</small></div><button type="button" class="icon-btn" data-edit-cue="${esc(c.id)}" aria-label="Editar cue">${icon('edit')}</button><button type="button" class="icon-btn" data-remove-cue="${esc(c.id)}" aria-label="Excluir cue">${icon('trash')}</button></div>`).join('')}`;
  if(tab==='timeline')content=`<p class="dialog-description">Eventos usam o tempo da cena ativa. Pausar preserva a posição; parar zera a timeline.</p><div class="config-list">${scene.timeline.map((t,i)=>`<div class="config-row"><span class="time-chip">${formatTime(t.at)}</span><div><strong>${esc(t.label)}</strong><small>${esc(({oneshot:'Efeito sonoro',fade:'Fade de camada',cue:'Cue composta'})[t.action]||t.action)}</small></div><button type="button" class="icon-btn" data-edit-event="${i}" aria-label="Editar evento">${icon('edit')}</button><button type="button" class="icon-btn" data-remove-event="${i}" aria-label="Remover evento">${icon('trash')}</button></div>`).join('')||'<p class="empty-small">Nenhum evento automático.</p>'}</div><button type="button" class="btn outline full" id="addEvent">${icon('plus')} Adicionar evento</button>`;
  openForm({title:`Direção · ${scene.title}`,body:`<div class="tab-pills config-tabs">${[['layers','Camadas'],['triggers','Gatilhos e cues'],['timeline','Timeline']].map(([key,label])=>`<button type="button" class="${tab===key?'active':''}" data-config-tab="${key}">${label}</button>`).join('')}</div>${content}`,onReady:root=>{
    $$('[data-config-tab]',root).forEach(b=>b.onclick=()=>openSceneConfig(ctx,b.dataset.configTab));
    const remove=(array,key,index=false)=>{const list=scene[array];const i=index?Number(key):list.findIndex(x=>x.id===key);if(i>=0)list.splice(i,1);ctx.commit();back();};
    $$('[data-remove-layer]',root).forEach(b=>b.onclick=()=>{if(ctx.engine.active?.key===ctx.location().key){const t=ctx.engine.tracks.get(b.dataset.removeLayer);ctx.engine.dispose(t);ctx.engine.tracks.delete(b.dataset.removeLayer);}remove('layers',b.dataset.removeLayer);});
    $$('[data-remove-trigger]',root).forEach(b=>b.onclick=()=>remove('triggers',b.dataset.removeTrigger));
    $$('[data-remove-event]',root).forEach(b=>b.onclick=()=>remove('timeline',b.dataset.removeEvent,true));
    $$('[data-remove-cue]',root).forEach(b=>b.onclick=()=>{
      const id=b.dataset.removeCue;scene.cues=scene.cues.filter(c=>c.id!==id);scene.triggers=scene.triggers.filter(t=>!t.cue||(t.cueId||t.id)!==id);scene.timeline=scene.timeline.filter(t=>t.cueId!==id);ctx.commit();back();
    });
    $$('[data-edit-layer]',root).forEach(b=>b.onclick=()=>editLayer(ctx,scene.layers.find(x=>x.id===b.dataset.editLayer),back));
    $$('[data-edit-trigger]',root).forEach(b=>b.onclick=()=>editTrigger(ctx,scene.triggers.find(x=>x.id===b.dataset.editTrigger),back));
    $$('[data-edit-cue]',root).forEach(b=>b.onclick=()=>editCue(ctx,scene.cues.find(x=>x.id===b.dataset.editCue),back));
    $$('[data-edit-event]',root).forEach(b=>b.onclick=()=>editEvent(ctx,Number(b.dataset.editEvent),back));
    $('#addLayer',root)?.addEventListener('click',()=>editLayer(ctx,null,back));
    $('#addTrigger',root)?.addEventListener('click',()=>editTrigger(ctx,null,back));
    $('#addCue',root)?.addEventListener('click',()=>editCue(ctx,null,back));
    $('#addEvent',root)?.addEventListener('click',()=>editEvent(ctx,null,back));
    $('#sceneMusic',root)?.addEventListener('change',e=>{scene.musicAssetId=e.target.value||null;ctx.commit();});
  }});
}
function editLayer(ctx,layer,back) {
  const assets=ctx.state().audioAssets.filter(a=>a.provider!=='youtube');
  if(!assets.length){toast('Adicione arquivos de áudio à biblioteca.',true);return;}
  openForm({title:layer?'Editar camada':'Adicionar camada',body:field('Nome da camada','name',layer?.name||'','required maxlength="100"')+`<label class="field"><span>Arquivo de áudio</span><select name="assetId" required>${assets.map(a=>option(a.id,a.name,a.id===layer?.assetId||a.src===layer?.src)).join('')}</select></label><div class="form-grid">${field('Volume (%)','volume',Math.round((layer?.volume??.5)*100),'type="number" min="0" max="100" required')}<label class="field"><span>Canal do mixer</span><select name="group">${['ambience','music','sfx'].map(g=>option(g,({ambience:'Ambiência',music:'Música',sfx:'Efeitos'})[g],g===(layer?.group||'ambience'))).join('')}</select></label></div><p class="form-hint">Todas as camadas fazem loop. A alteração entra ao iniciar a cena novamente.</p>`,onSubmit:form=>{
    const asset=assets.find(a=>a.id===form.get('assetId'));const value={id:layer?.id||uid('layer'),name:String(form.get('name')).trim(),assetId:asset.id,src:asset.src||null,volume:Number(form.get('volume'))/100,type:'LOOP',group:form.get('group')};
    if(!value.name)throw new Error('Informe um nome para a camada.');if(layer)Object.assign(layer,value);else ctx.scene().layers.push(value);ctx.commit();return back;
  }});
}
function editTrigger(ctx,trigger,back) {
  const scene=ctx.scene(),assets=ctx.state().audioAssets.filter(a=>a.provider!=='youtube');
  openForm({title:trigger?'Editar gatilho':'Adicionar gatilho',body:field('Nome do botão','name',trigger?.name||'','required maxlength="90"')+`<label class="field"><span>Efeito ou cue</span><select name="target" required>${assets.map(a=>option('asset:'+a.id,a.name,!trigger?.cue&&(a.id===trigger?.assetId||a.src===trigger?.src))).join('')}${(scene.cues||[]).map(c=>option('cue:'+c.id,'Cue · '+c.name,trigger?.cue&&(trigger.cueId||trigger.id)===c.id)).join('')}</select></label><div class="form-grid">${field('Atalho (1 a 9, opcional)','key',trigger?.key||'','maxlength="1" pattern="[1-9]" inputmode="numeric"')}${field('Volume do efeito (%)','volume',Math.round((trigger?.volume??.8)*100),'type="number" min="0" max="100" required')}</div>`,onSubmit:form=>{
    const key=String(form.get('key')).trim();if(key&&scene.triggers.some(t=>t!==trigger&&t.key===key))throw new Error('Este atalho já está em uso nesta cena.');
    const target=String(form.get('target'));if(!target)throw new Error('Escolha um arquivo ou uma cue.');const isCue=target.startsWith('cue:'),id=target.slice(target.indexOf(':')+1);const asset=assets.find(a=>a.id===id);
    const value={id:trigger?.id||uid('trigger'),name:String(form.get('name')).trim(),key,cue:isCue,cueId:isCue?id:null,assetId:!isCue?id:null,src:asset?.src||null,volume:Number(form.get('volume'))/100};
    if(!value.name)throw new Error('Informe um nome.');if(trigger)Object.assign(trigger,value);else scene.triggers.push(value);ctx.commit();return back;
  }});
}
function editEvent(ctx,index,back) {
  const scene=ctx.scene(),event=index===null?null:scene.timeline[index],assets=ctx.state().audioAssets.filter(a=>a.provider!=='youtube');
  openForm({title:event?'Editar evento':'Evento automático',body:field('Descrição','label',event?.label||'','required maxlength="120"')+`<div class="form-grid">${field('Disparar em (segundos)','at',event?.at??10,'type="number" min="0" step="0.1" required')}<label class="field"><span>Ação</span><select name="action" id="eventAction">${[['oneshot','Tocar efeito'],['fade','Fade de camada'],['cue','Disparar cue']].map(([v,l])=>option(v,l,v===(event?.action||'oneshot'))).join('')}</select></label></div><div data-event-fields="oneshot"><label class="field"><span>Áudio</span><select name="assetId">${assets.map(a=>option(a.id,a.name,a.id===event?.assetId||a.src===event?.src)).join('')}</select></label></div><div data-event-fields="fade"><label class="field"><span>Camada</span><select name="layer">${scene.layers.map(l=>option(l.id,l.name,l.id===event?.layer)).join('')}</select></label><div class="form-grid">${field('Volume de destino (%)','to',Math.round((event?.to??0)*100),'type="number" min="0" max="100"')}${field('Duração do fade (s)','duration',event?.duration??2,'type="number" min="0" max="120" step="0.1"')}</div></div><div data-event-fields="cue"><label class="field"><span>Cue composta</span><select name="cueId">${(scene.cues||[]).map(c=>option(c.id,c.name,c.id===event?.cueId)).join('')}</select></label></div>`,onReady:root=>{const show=()=>$$('[data-event-fields]',root).forEach(el=>{el.hidden=el.dataset.eventFields!==$('#eventAction',root).value;$$('input,select',el).forEach(i=>i.disabled=el.hidden);});$('#eventAction',root).onchange=show;show();},onSubmit:form=>{
    const action=form.get('action'),asset=assets.find(a=>a.id===form.get('assetId'));
    if(action==='fade'&&!form.get('layer'))throw new Error('Adicione uma camada antes de configurar um fade.');if(action==='cue'&&!form.get('cueId'))throw new Error('Crie uma cue antes de adicioná-la à timeline.');if(action==='oneshot'&&!asset)throw new Error('Escolha um arquivo de áudio.');
    const value={at:Number(form.get('at')),label:String(form.get('label')).trim(),action,assetId:asset?.id,src:asset?.src,layer:form.get('layer'),to:Number(form.get('to'))/100,duration:Number(form.get('duration')),cueId:form.get('cueId')};
    if(!value.label)throw new Error('Informe uma descrição.');if(event)scene.timeline[index]=value;else scene.timeline.push(value);scene.timeline.sort((a,b)=>a.at-b.at);ctx.commit();return back;
  }});
}
function editCue(ctx,cue,back) {
  const scene=ctx.scene(),assets=ctx.state().audioAssets.filter(a=>a.provider!=='youtube');
  const actions=structuredClone(cue?.actions||[{type:'play',assetId:assets[0]?.id,volume:.8,delay:0}]);
  const body=field('Nome da cue','name',cue?.name||'','required maxlength="100"')+'<p class="form-hint">O atraso é contado desde o clique. Use várias ações para montar a transição.</p><div id="cueActions"></div><button type="button" class="btn outline full" id="addCueAction">+ Adicionar ação</button>';
  function readRows(root){$$('.cue-action-row',root).forEach((el,i)=>{actions[i]={type:$('[data-action-type]',el).value,assetId:$('[data-action-asset]',el).value,layerId:$('[data-action-layer]',el).value,volume:Number($('[data-action-volume]',el).value)/100,to:Number($('[data-action-volume]',el).value)/100,delay:Number($('[data-action-delay]',el).value),duration:Number($('[data-action-duration]',el).value)};});}
  function render(root){$('#cueActions',root).innerHTML=actions.map((a,i)=>`<div class="cue-action-row"><div class="cue-action-heading"><b>AÇÃO ${i+1}</b><button type="button" class="icon-btn" data-remove-action="${i}" aria-label="Excluir ação">${icon('trash')}</button></div><div class="form-grid"><label class="field"><span>Ação</span><select data-action-type>${[['play','Tocar efeito'],['fade','Fade de camada'],['stop','Parar camada']].map(([v,l])=>option(v,l,v===a.type)).join('')}</select></label><label class="field"><span>Atraso (s)</span><input data-action-delay type="number" min="0" max="600" step="0.1" value="${Number(a.delay)||0}" required></label></div><label class="field" ${a.type!=='play'?'hidden':''}><span>Áudio</span><select data-action-asset>${assets.map(x=>option(x.id,x.name,x.id===a.assetId)).join('')}</select></label><label class="field" ${a.type==='play'?'hidden':''}><span>Camada</span><select data-action-layer>${scene.layers.map(l=>option(l.id,l.name,l.id===a.layerId)).join('')}</select></label><div class="form-grid" ${a.type==='stop'?'hidden':''}><label class="field"><span>${a.type==='fade'?'Volume de destino':'Volume'} (%)</span><input data-action-volume type="number" min="0" max="100" value="${Math.round((a.type==='fade'?a.to??0:a.volume??.8)*100)}" required></label><label class="field" ${a.type!=='fade'?'hidden':''}><span>Duração (s)</span><input data-action-duration type="number" min="0" max="120" step="0.1" value="${Number(a.duration)||1}"></label></div></div>`).join('');
    $$('[data-action-type]',root).forEach(el=>el.onchange=()=>{readRows(root);render(root);});$$('[data-remove-action]',root).forEach(el=>el.onclick=()=>{readRows(root);actions.splice(+el.dataset.removeAction,1);render(root);});
  }
  openForm({title:cue?'Editar cue composta':'Nova cue composta',body,wide:true,onReady:root=>{render(root);$('#addCueAction',root).onclick=()=>{readRows(root);actions.push({type:'play',assetId:assets[0]?.id,delay:0,volume:.8});render(root);};},onSubmit:form=>{
    readRows($('#dialogBody'));if(!actions.length)throw new Error('Adicione pelo menos uma ação.');if(actions.some(a=>a.type==='play'&&!a.assetId||a.type!=='play'&&!a.layerId))throw new Error('Selecione o áudio ou a camada para cada ação.');
    const name=String(form.get('name')).trim();if(!name)throw new Error('Informe um nome.');if(cue){cue.name=name;cue.actions=actions;}else{const value={id:uid('cue'),name,actions};scene.cues??=[];scene.cues.push(value);scene.triggers.push({id:uid('trigger'),name,cue:true,cueId:value.id,key:''});}
    ctx.commit();return back;
  }});
}
